function run(paymentStatusFeedbackTime, inputCheckout, customerCardsResponse, checkoutRequest) {

            const regexOutraForma = /outra\s+forma/i;
            const regexCartaoFinal = /cart[a\u00e3]o\s+final/i;

    paymentStatusFeedbackTime = Number(paymentStatusFeedbackTime);
    const customerCards =  typeof customerCardsResponse === 'string' ? JSON.parse(customerCardsResponse) : null;        
    checkoutRequest = JSON.parse(checkoutRequest);

	if(checkoutRequest.step === 'link') {
		return paymentStatusFeedbackTime;
	}		

	if (paymentStatusFeedbackTime <= 0 || (checkoutRequest.step === 'wait' && inputCheckout && !regexOutraForma.test(inputCheckout) || inputCheckout && regexCartaoFinal.test(inputCheckout))) {
		return 0;
	}

	return paymentStatusFeedbackTime - 1;
}

function run(configurationData, customizeData, paymentMethodData, checkoutResponse, customerCardsResponse, inputCheckout, checkoutRequest) {

    // Função auxiliar para parse robusto de JSON (com ou sem JSON.stringify)
    const safeJsonParse = (data) => {
        if (!data) return null;

        // Se já é objeto, retorna diretamente
        if (typeof data === 'object') return data;

        try {
            // Primeiro parse (JSON normal)
            let parsed = JSON.parse(data);

            // Se ainda for string, tenta segundo parse (caso JSON.stringify duplo)
            if (typeof parsed === 'string') {
                parsed = JSON.parse(parsed);
            }

            return parsed;
        } catch (e) {
            // Tratamento específico para formato Blip
            try {
                // Verifica se tem o padrão típico do erro do Blip
                if (data.includes('"items":"[{') && data.includes('}]"')) {
                    // Extrai os componentes manualmente usando regex
                    const refMatch = data.match(/"referenceId":"([^"]+)"/);
                    const typeMatch = data.match(/"productType":"([^"]+)"/);
                    const valueMatch = data.match(/"value":"([^"]*)"/);

                    // Extrai e corrige o campo items
                    const itemsMatch = data.match(/"items":"(\[.*?\])"/);

                    if (refMatch && typeMatch && itemsMatch) {
                        return {
                            referenceId: refMatch[1],
                            productType: typeMatch[1],
                            items: itemsMatch[1],
                            value: valueMatch ? valueMatch[1] : ""
                        };
                    }
                }

                // Se não conseguiu aplicar o fix específico, tenta outras abordagens
                const unescaped = data.replace(/\"/g, '"');
                return JSON.parse(unescaped);

            } catch (e2) {
                return null;
            }
        }
    };

    // Verificar se deve mostrar order details:
    // 1. Usuário não tem cartão salvo, OU
    // 2. Usuário escolheu Outra forma (ACCESS_PAYMENT_LINK)

    let shouldShowOrderDetails = false;

    // Verificar se não tem cartão salvo
    let hasCard = false;
    try {
        const cardData = safeJsonParse(customerCardsResponse);
        hasCard = cardData && cardData.hasSavedCard === true;
    } catch (e) {
        hasCard = false;
    }

    if (!hasCard) {
        shouldShowOrderDetails = true;
    }

    // Processar order details normalmente
    let productType = "digital";
    let referenceId = "";
    let items = [];

    checkoutResponse = safeJsonParse(checkoutResponse);

    try {
        const configData = safeJsonParse(configurationData);

        if (configData && configData.items) {
            let itemsArray = [];

            // Se items já for um array, usa diretamente
            if (Array.isArray(configData.items)) {
                itemsArray = configData.items;
            }
            // Se items for uma string JSON, faz o parse
            else if (typeof configData.items === "string") {
                try {
                    itemsArray = JSON.parse(configData.items);
                } catch (e) {
                    itemsArray = [];
                }
            }

            if (Array.isArray(itemsArray) && itemsArray.length > 0) {
                itemsArray.forEach(item => {
                    items.push({
                        retailer_id: item.retailer_product_id || item.retailer_id || "",
                        name: item.name || "",
                        amount: {
                            value: Math.round((item.amount.value || 0) * 100),
                            offset: 100
                        },
                        quantity: item.quantity || 1
                    });
                });

                referenceId = configData.referenceId || "";
                productType = configData.productType || "digital";
            }
        } else {
            // Fallback para processamento por regex (formato legacy)
            const refMatch = configurationData && configurationData.match(/"referenceId"\s*:\s*"([^"]+)"/);
            const typeMatch = configurationData && configurationData.match(/"productType"\s*:\s*"([^"]+)"/);

            referenceId = refMatch ? refMatch[1] : "";
            productType = typeMatch ? typeMatch[1] : "digital";

            const itemsMatch = configurationData && configurationData.match(/"items"\s*:\s*"(.+?)"/s);

            if (itemsMatch) {
                let itemsStr = itemsMatch[1];

                try {
                    // Tentar parse direto da string JSON
                    const itemsArray = JSON.parse(itemsStr);
                    if (Array.isArray(itemsArray)) {
                        itemsArray.forEach(item => {
                            items.push({
                                retailer_id: item.retailer_product_id || item.retailer_id || "",
                                name: item.name || "",
                                amount: {
                                    value: Math.round((item.amount.value || 0) * 100),
                                    offset: 100
                                },
                                quantity: item.quantity || 1
                            });
                        });
                    }
                } catch (e) {
                    // Se falhar, usar a lógica de regex original
                    itemsStr = itemsStr.replace(/\"/g, '"').replace(/"/g, '"');

                    const objectRegex = /{[^{}]*{[^{}]*}[^{}]*}/g;
                    const matches = itemsStr.match(objectRegex);

                    if (matches) {
                        for (let i = 0; i < matches.length; i++) {
                            const part = matches[i].trim();

                            const retailerMatch = part.match(/"retailer_product_id"\s*:\s*"([^"]+)"/) || part.match(/"retailer_id"\s*:\s*"([^"]+)"/);
                            const nameMatch = part.match(/"name"\\s*:\\s*"([^"]+)"/);
                            const valueMatch = part.match(/"value"\s*:\s*(\d+)/);
                            const quantityMatch = part.match(/"quantity"\\s*:\\s*(\\d+)/);

                            if (retailerMatch && nameMatch && valueMatch && quantityMatch) {
                                items.push({
                                    retailer_id: retailerMatch[1],
                                    name: nameMatch[1],
                                    amount: {
                                        value: parseInt(valueMatch[1]),
                                        offset: 100
                                    },
                                    quantity: parseInt(quantityMatch[1])
                                });
                            }
                        }
                    }
                }
            }
        }
    } catch (e) {
        items = [];
    }

    let totalValue = 0;
    for (let i = 0; i < items.length; i++) {
        totalValue += items[i].amount.value * items[i].quantity;
    }

    let textBody = "";
    let textFooter = "";
    try {
        const customData = safeJsonParse(customizeData);
        if (customData) {
            textBody = customData.textBody || "";
            textFooter = customData.textFooter || "";
        }
    } catch (e) {}

    const mapKeyType = (keyType) => {
        const map = {
            'cpf': 'CPF',
            'cnpj': 'CNPJ',
            'email': 'EMAIL',
            'telefone': 'PHONE',
            'random': 'RANDOM_KEY'
        };
        return map[(keyType || '').toLowerCase()] || (keyType || 'EMAIL').toUpperCase();
    };

    let paymentSettings = [];

    var paymentProcessError = null;

    try {
        const paymentData = safeJsonParse(paymentMethodData);

        if (paymentData) {
            const processMethod = (method) => {
                if (!method || !method.type) return;

                if (method.type === "pixcopycode" && method.config && method.config.provider === "own") {
                    paymentSettings.push({
                        type: "pix_dynamic_code",
                        pix_dynamic_code: {
                            code: method.config.pixCode || "",
                            merchant_name: method.config.business || "",
                            key: method.config.pixKey || method.config.business || "",
                            key_type: mapKeyType(method.config.keyType || "email")
                        }
                    });
                }
                else if (method.type === "pixcopycode" && method.config && method.config.provider === "checkout") {
                    // Tentar extrair o código PIX de diferentes campos possíveis na resposta do checkout
                    var pixCode = "";
                    if (checkoutResponse && checkoutResponse.status === "created") {
                        pixCode = checkoutResponse.pixQrCodeText
                            || (checkoutResponse.rawApiResponse && (
                                checkoutResponse.rawApiResponse.pixQrCodeText
                                || (checkoutResponse.rawApiResponse.pix && checkoutResponse.rawApiResponse.pix.qrCodeText)
                                || checkoutResponse.rawApiResponse.pixCode
                                || (checkoutResponse.rawApiResponse.pix && checkoutResponse.rawApiResponse.pix.copyAndPaste)
                            ))
                            || "";
                    }
                    if (!pixCode) {
                        paymentProcessError = 'PIX_CODE_EMPTY: Checkout API did not return a PIX code. checkoutStatus=' + (checkoutResponse ? checkoutResponse.status : 'null');
                        return;
                    }
                    paymentSettings.push({
                        type: "pix_dynamic_code",
                        pix_dynamic_code: {
                            code: pixCode,
                            merchant_name: checkoutResponse.pixName || "",
                            key: checkoutResponse.pixKey || "",
                            key_type: "CNPJ"
                        }
                    });
                }
                else if (method.type === "paymentlink" && method.config) {
                    if (method.config.provider === "own") {
                        paymentSettings.push({
                            type: "payment_link",
                            payment_link: {
                                uri: method.config.httpsLink || method.config.paymentUrl || ""
                            }
                        });
                    }
                    else if (method.config.provider === "checkout") {
                        let checkoutLink = "";
                        if (checkoutResponse && checkoutResponse.link && checkoutResponse.status === "created") {
                            checkoutLink = checkoutResponse.link;
                        }

                        const checkoutSettings = {
                            type: "payment_link",
                            payment_link: {
                                uri: checkoutLink || "#"
                            }
                        };                        

                        paymentSettings.push(checkoutSettings);
                    }
                }
                else if (method.type === "boleto" && method.config && method.config.provider === "own") {
                    paymentSettings.push({
                        type: "boleto",
                        boleto: {
                            digitable_line: method.config.boletoCode || ""
                        }
                    });
                }
            };

            processMethod(paymentData.method1);
            if (paymentProcessError) {
                return JSON.stringify({ status: 'Error', result: paymentProcessError });
            }

            if (paymentData.showMethod2) {
                processMethod(paymentData.method2);
                if (paymentProcessError) {
                    return JSON.stringify({ status: 'Error', result: paymentProcessError });
                }
            }
        }
    } catch (e) {
        paymentSettings = [];
    }

    const parsedJSON = {
        type: "interactive",
        interactive: {
            type: "order_details",
            body: {
                text: textBody || "Detalhes do seu pedido:"
            },
            action: {
                name: "review_and_pay",
                parameters: {
                    reference_id: referenceId || "REF" + Date.now(),
                    type: productType === "fisico" ? "physical-goods" : "digital-goods",
                    payment_type: "br",
                    currency: "BRL",
                    total_amount: {
                        value: totalValue,
                        offset: 100
                    },
                    order: {
                        status: "pending",
                        items: items,
                        subtotal: {
                            value: totalValue,
                            offset: 100
                        }
                    },
                    payment_settings: paymentSettings
                }
            }
        }
    };

    if (textFooter) {
        parsedJSON.interactive.footer = { text: textFooter };
    }

    const isValidCPF = function(cpf) {
        const cleaned = cpf.replace(/\D/g, '');
        return (
            /^\d{11}$/.test(cleaned) &&
            !new RegExp('(\d)\1{10}').test(cleaned)
        );
    };
    const isValidCNPJ = function(cnpj) {
        const cleaned = cnpj.replace(/\D/g, '');
        return (
            /^\d{14}$/.test(cleaned) &&
            !new RegExp('(\d)\1{13}').test(cleaned)
        );
    };
    const isValidEmail = (email) => {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    };
    const isValidLink = (url) => {
        const cleaned = (url || '').trim();
        // Permitir links vazios, "#" ou links válidos
        if (cleaned === "" || cleaned === "#") return true;
        const regex = /^(https?:\/\/)(?!javascript:|data:)(?:[A-Za-z0-9-._~%]+@)?(?:(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,}|localhost|\d{1,3}(?:\.\d{1,3}){3})(?::\d{2,5})?(?:[\/\?#][^\s]*)?$/i;
        return regex.test(cleaned);
    };
    const isValidBoleto = (boleto) => {
        const cleaned = boleto.replace(/\D/g, '');
        return /^\d{47,48}$/.test(cleaned);
    };

    // Validar estrutura básica
    if (!parsedJSON.interactive || !parsedJSON.interactive.action || !parsedJSON.interactive.action.parameters) {
        return JSON.stringify({ status: 'Error', result: 'ORDER DETAILS JSON STRUCTURE ERROR' });
    }                            

    // Garantir corpo de texto não-vazio (obrigatório para WhatsApp)
    if (!parsedJSON.interactive.body || !parsedJSON.interactive.body.text) {
        parsedJSON.interactive.body = { text: "Detalhes do seu pedido:" };
    }

    const params = parsedJSON.interactive.action.parameters;

    // Validar referência
    if (!params.reference_id || params.reference_id.trim() === "") {
        return JSON.stringify({ status: 'Error', result: 'ORDER REFERENCE ERROR' });
    }

    // Validar itens do pedido
    if (!params.order || !Array.isArray(params.order.items) || params.order.items.length === 0) {
        return JSON.stringify({ status: 'Error', result: 'ORDER ITEMS ERROR' });
    }

    // Validar métodos de pagamento
    if (!Array.isArray(params.payment_settings) || params.payment_settings.length === 0) {
        return JSON.stringify({ status: 'Error', result: 'PAYMENT SETTINGS ERROR' });
    }

    // Validar payment_settings
    if (parsedJSON.interactive && parsedJSON.interactive.action && parsedJSON.interactive.action.parameters) {
        const params = parsedJSON.interactive.action.parameters;
        if (Array.isArray(params.payment_settings)) {
            for (let i = 0; i < params.payment_settings.length; i++) {
                const setting = params.payment_settings[i];
                if (setting.type === 'payment_link' && setting.payment_link) {
                    // Só validar link se não for vazio ou "#"
                    const uri = setting.payment_link.uri || '';
                    if (uri !== '' && uri !== '#' && !isValidLink(uri)) {
                        return JSON.stringify({ status: 'Error', result: 'PAYMENT LINK ERROR: ' + uri });
                    }
                } else if (setting.type === 'pix_dynamic_code' && setting.pix_dynamic_code) {
                    const keyType = (setting.pix_dynamic_code.key_type || '').toUpperCase();
                    const key = setting.pix_dynamic_code.key || '';
                    // Só validar se a chave não estiver vazia
                    if (key) {
                        if (keyType === 'CPF' && !isValidCPF(key)) {
                            return JSON.stringify({ status: 'Error', result: 'CPF ERROR: ' + key });
                        } else if (keyType === 'CNPJ' && !isValidCNPJ(key)) {
                            return JSON.stringify({ status: 'Error', result: 'CNPJ ERROR: ' + key });
                        } else if (keyType === 'EMAIL' && !isValidEmail(key)) {
                            return JSON.stringify({ status: 'Error', result: 'EMAIL ERROR: ' + key });
                        }
                    }
                } else if (setting.type === 'boleto' && setting.boleto) {
                    const boletoCode = setting.boleto.digitable_line || '';
                    // Só validar se o código não estiver vazio
                    if (boletoCode && !isValidBoleto(boletoCode)) {
                        return JSON.stringify({ status: 'Error', result: 'BOLETO ERROR: ' + boletoCode });
                    }
                }
            }
        }
    }

    return JSON.stringify(parsedJSON, null, 2);
}

function run(orderDetailsJSON, inputCheckout, paymentMethodData, paymentStatusFeedbackTime, customerCardsResponse) {
                      try {
                            const regexUnexpectedInput = /^(?!.*(?:cart[a\u00e3]o\s+final|outra\s+forma)).*$/i;
                            const regexOutraForma = /outra\s+forma/i;
                            const regexCartaoFinal = /cart[a\u00e3]o\s+final/i;
                            paymentMethodData = JSON.parse(paymentMethodData);                           

                            const customerCards =  typeof customerCardsResponse === 'string' ? JSON.parse(customerCardsResponse) : null;            

                            if((((paymentMethodData.method1 && (paymentMethodData.method1.type === "paymentlink" || paymentMethodData.method1.type === "pixcopycode") && paymentMethodData.method1.config.provider === "checkout")) || 
                               (paymentMethodData.method2 && (paymentMethodData.method2.type === "paymentlink" || paymentMethodData.method2.type === "pixcopycode") && paymentMethodData.method2.config.provider === "checkout")) &&                                 
                                (inputCheckout && regexUnexpectedInput.test(inputCheckout) ) && customerCards && customerCards.hasSavedCard === true) {
                                    return 'UnexpectedInput';
                            }

                             if (!orderDetailsJSON) {
                                return '';
                            }

                            // Verificar se o generate script retornou um erro (ex: PIX_CODE_EMPTY)
                            // Isso deve ser checado ANTES do Loopback para não enviar JSON inválido ao WhatsApp
                            try {
                                var quickCheck = JSON.parse(orderDetailsJSON);
                                if (quickCheck && quickCheck.status === 'Error') {
                                    return 'Error';
                                }
                            } catch (qe) { /* ignorar parse error aqui, será tratado abaixo */ }

                            if(inputCheckout && regexCartaoFinal.test(inputCheckout)) {
                                return 'WithoutComponent';
                            } 

                            if(inputCheckout && regexOutraForma.test(inputCheckout) || paymentStatusFeedbackTime > 0) {
                                return 'Loopback';
                            }                                                       

                            const parsedJSON = JSON.parse(orderDetailsJSON);                          

                            if (
                                parsedJSON.type === "interactive" &&
                                parsedJSON.interactive &&
                                parsedJSON.interactive.type === "order_details"
                            ) {
                                return 'Success';
                            }

                            return 'Error';
                        } catch (e) {
                            return 'Error';
                        }
                    }

