        (paymentData && paymentData.showMethod2 && isCheckoutMethod(paymentData.method2)));
}

function getHeaders(token) {
    return {
        Authorization: `Bearer ${token}`
    };
}

async function execFetch(url, options) {
    try {
        const response = await request.fetchAsync(url, options);

        let parsedBody;
        try {
            parsedBody = await response.jsonAsync();
        } catch (e) {
            parsedBody = await response; 
        }

        return {
             status: response.status,
             body: parsedBody
        }
    } catch (error) {
        throw error;
    }
}

async function getToken(checkoutRequest, urlBase, secret) {
    const bodyRequest = {
        botShortName: checkoutRequest.botShortName,
        secret: secret
    };

    let response = await execFetch(`${urlBase}/bot`, {
            method: 'POST',
            body: bodyRequest
        });

    return {
        status: response.status,
        body: response.body && response.body.token ? response.body.token : response.body
    }
}

async function getPaymentResponse(checkoutId, token, urlBase) {    
    try {
        var response = await execFetch(`${urlBase}/V0.1/payment?id=${checkoutId}`, { 
            method: 'GET', 
            headers: getHeaders(token)       
        });  

        return {
            status: response.status,
            body: response.body
        }
    } catch (error) {
        throw error;
    }
}


async function ProcessPaymentWithSavedCard(purchaseId, cardId, token, urlBase) {    
    try {
        const bodyRequest = {
            id: cardId,
            installments: 1
        };

        var response = await execFetch(`${urlBase}/V0.1/payment/saved-card?id=${purchaseId}`, { 
            method: 'POST', 
            body: bodyRequest,
            headers: getHeaders(token)       
        });  

        return {
            status: response.status,
            body: response.body
        }
    } catch (error) {
        throw error;
    }
}

async function run(checkoutResponse, checkoutRequest, customerCardsResponse, checkoutConfig, checkoutSecretCommandResponse) {

     try {        
        const config = typeof checkoutConfig === 'string' ? JSON.parse(checkoutConfig) : checkoutConfig;
        const URL_BASE = config.baseUrl;
        const URL_BASE_AUTH = config.authUrl;
        const secretResponse = typeof checkoutSecretCommandResponse === 'string' ? JSON.parse(checkoutSecretCommandResponse) : checkoutSecretCommandResponse;
        const SECRET = secretResponse && secretResponse.resource ? secretResponse.resource : null;
        if (!SECRET) throw new Error('Falha ao ler bucket checkout-secret: Bucket "checkout-secret" não encontrado ou vazio');

        const checkoutData = typeof checkoutResponse === 'string' ? JSON.parse(checkoutResponse) : checkoutResponse;
        const requestData = typeof checkoutRequest === 'string' ? JSON.parse(checkoutRequest) : checkoutRequest;
        const cardData = typeof customerCardsResponse === 'string' ? JSON.parse(customerCardsResponse) : customerCardsResponse;
        const card = cardData.card;

        let urlBase = URL_BASE;
        let urlAuthBase = URL_BASE_AUTH;
        let response = { status: 'error' };        

        try {
            let responsePayment = await ProcessPaymentWithSavedCard(checkoutData.checkoutId, card.id, checkoutData.botToken, urlBase);

            if (Number(responsePayment.status) === 401) {
                const responseToken = await getToken(requestData, urlAuthBase, SECRET);
                if (Number(responseToken.status) === 200) {
                    responsePayment = await ProcessPaymentWithSavedCard(checkoutData.checkoutId, card.id, responseToken.body, urlBase);
                }
            }

            if (Number(responsePayment.status) === 200 && responsePayment.body) {
                response = {
                    status: 'success', 
                    body: responsePayment.body            
                };
            } else {
                response = {
                    status: 'error',
                    message: 'Erro ao processar pagamento',
                    httpStatus: responsePayment.status,
                    details: responsePayment.body
                };
            }

        } catch (apiError) {
            response = {
                status: 'error', 
                message: 'Erro no request da API: ' + apiError.message                    
            };
        }    

    return JSON.stringify(response);

    } catch (error) {
        return JSON.stringify({ status: 'error', message: 'Erro ao processar pagamento: ' + error.message });
    }
}

