async function run(paymentMethodData, checkoutResponse, checkoutRequest, checkoutConfig, checkoutSecretCommandResponse, inputCheckout, oneClickPaymentResult) {
    try {
        const config = typeof checkoutConfig === 'string' ? JSON.parse(checkoutConfig) : checkoutConfig;
        const URL_BASE = config.baseUrl;
        const URL_BASE_AUTH = config.authUrl;
        const secretResponse = typeof checkoutSecretCommandResponse === 'string' ? JSON.parse(checkoutSecretCommandResponse) : checkoutSecretCommandResponse;
        const SECRET = secretResponse && secretResponse.resource ? secretResponse.resource : null;
        if (!SECRET) throw new Error('Falha ao ler bucket checkout-secret: Bucket "checkout-secret" não encontrado ou vazio');

        const paymentData = typeof paymentMethodData === 'string' ? JSON.parse(paymentMethodData) : paymentMethodData;
        const checkoutData = typeof checkoutResponse === 'string' ? JSON.parse(checkoutResponse) : checkoutResponse;
        const requestData = typeof checkoutRequest === 'string' ? JSON.parse(checkoutRequest) : checkoutRequest;

        // Verificar se algum método tem feedback habilitado
        const method1HasFeedback = paymentData.method1 && paymentData.method1.config &&
            paymentData.method1.config.paymentReturn &&
            paymentData.method1.config.paymentReturn.feedbackReturnPayment;
        const method2HasFeedback = paymentData.showMethod2 && paymentData.method2 &&
            paymentData.method2.config &&
            paymentData.method2.config.paymentReturn &&
            paymentData.method2.config.paymentReturn.feedbackReturnPayment;

        if (!method1HasFeedback && !method2HasFeedback) {
            return { status: 'disabled', message: 'Feedback de pagamento desabilitado' };
        }

        if (!checkoutData || !requestData) {
            return { status: 'error', message: 'Dados do checkout não encontrados' };
        }

        const paymentId = checkoutData.checkoutId;
        if (!paymentId) {
            return { status: 'error', message: 'ID do pagamento não encontrado no resultado do checkout' };
        }

        // Verificar status do pagamento via API
        let urlBase = URL_BASE;
        let urlAuthBase = URL_BASE_AUTH;
        let paymentStatus = 'unknown';
        let paymentMethodFromApi = 'None';

        const parseJsonSafe = (value) => {
            if (!value) {
                return null;
            }
            if (typeof value === 'object') {
                return value;
            }
            try {
                return JSON.parse(value);
            } catch (e) {
                return null;
            }
        };

        const wait = async (ms) => {
            if (typeof setTimeout !== 'function') {
                return;
            }
            await new Promise(resolve => setTimeout(resolve, ms));
        };

        const isFinalPaymentStatus = (status) => status === 'Succeeded' || status === 'Denied' || status === 'Failed';
        const hasUserInput = typeof inputCheckout === 'string' && inputCheckout.trim().length > 0;

        let isSavedCardFlow = false;
        const oneClickResult = parseJsonSafe(oneClickPaymentResult);
        if (oneClickResult && oneClickResult.status === 'success') {
            isSavedCardFlow = true;
        }

        if (!isSavedCardFlow && typeof inputCheckout === 'string') {
            const regexCartaoFinal = /cart[aã]o +final/i;
            isSavedCardFlow = regexCartaoFinal.test(inputCheckout);
        }

        if (isSavedCardFlow) {
            const hasPaymentLink =
                (paymentData.method1 && paymentData.method1.type === 'paymentlink') ||
                (paymentData.showMethod2 && paymentData.method2 && paymentData.method2.type === 'paymentlink');
            if (!hasPaymentLink) isSavedCardFlow = false;
        }

        const fetchPaymentStatus = async () => {
            let responsePayment = await getPaymentResponse(checkoutData.checkoutId, checkoutData.botToken, urlBase);

            if (Number(responsePayment.status) === 401) {
                const responseToken = await getToken(requestData, urlAuthBase, SECRET);
                if (Number(responseToken.status) === 200) {
                    responsePayment = await getPaymentResponse(checkoutData.checkoutId, responseToken.body, urlBase);
                }
            }

            if (Number(responsePayment.status) === 200 && responsePayment.body) {
                if (responsePayment.body.status) {
                    paymentStatus = responsePayment.body.status;
                }
                if (responsePayment.body.paymentMethod) {
                    paymentMethodFromApi = responsePayment.body.paymentMethod;
                }
            }
        };

        try {
            if (isSavedCardFlow) {
                // Saved-card flow with user input: check immediately once, then continue retries.
                if (hasUserInput) {
                    await fetchPaymentStatus();
                }

                // Saved-card flow: wait 15s, query; wait 15s, query; wait 15s, query.
                // Exit early only when status is final.
                for (let attempt = 0; attempt < 3; attempt++) {
                    if (isFinalPaymentStatus(paymentStatus)) {
                        break;
                    }

                    await wait(15000);
                    await fetchPaymentStatus();
                    if (isFinalPaymentStatus(paymentStatus)) {
                        break;
                    }
                }
            } else {
                await fetchPaymentStatus();
            }
        } catch (apiError) {
            // Se falhar na API, continuar com status unknown
            paymentStatus = 'unknown';
        }

        // Identificar qual método é Pix vs CreditCard
        const method1Type = paymentData.method1 && paymentData.method1.type;
        const method2Type = paymentData.showMethod2 && paymentData.method2 && paymentData.method2.type;
        const method1IsPix = method1Type === 'pixcopycode';
        const method2IsPix = method2Type === 'pixcopycode';
        const method1IsCard = method1Type === 'paymentlink';
        const method2IsCard = method2Type === 'paymentlink';

        // Selecionar configuração de feedback baseada no paymentMethod retornado pela API:
        // - "Pix"        → usar configuração do método pixcopycode
        // - "CreditCard" → usar configuração do método paymentlink
        // - "None" ou não encontrado → usar método 1 como fallback
        let selectedFeedback = null;

        if (paymentMethodFromApi === 'Pix') {
            if (method1IsPix && method1HasFeedback) {
                selectedFeedback = paymentData.method1.config.paymentReturn;
            } else if (method2IsPix && method2HasFeedback) {
                selectedFeedback = paymentData.method2.config.paymentReturn;
            }
        } else if (paymentMethodFromApi === 'CreditCard') {
            if (method1IsCard && method1HasFeedback) {
                selectedFeedback = paymentData.method1.config.paymentReturn;
            } else if (method2IsCard && method2HasFeedback) {
                selectedFeedback = paymentData.method2.config.paymentReturn;
            }
        }

        // Fallback: paymentMethod === "None" ou correspondência não encontrada → usar método 1
        if (!selectedFeedback) {
            if (method1HasFeedback) {
                selectedFeedback = paymentData.method1.config.paymentReturn;
            } else if (method2HasFeedback) {
                selectedFeedback = paymentData.method2.config.paymentReturn;
            }
        }

        if (!selectedFeedback) {
            return { status: 'disabled', message: 'Feedback de pagamento desabilitado' };
        }

        const feedbackTimeMinutes = selectedFeedback.paymentStatusFeedbackTime || 1;
        const feedbackTimeSeconds = feedbackTimeMinutes * 60;

        // Verificar se checkout é o único método configurado
        const hasMethod1 = paymentData.method1 && paymentData.method1.type && paymentData.method1.type.trim() !== '';
        const hasMethod2 = paymentData.showMethod2 && paymentData.method2 && paymentData.method2.type && paymentData.method2.type.trim() !== '';
        const method1IsCheckout = hasMethod1 && isCheckoutMethod(paymentData.method1);
        const method2IsCheckout = hasMethod2 && isCheckoutMethod(paymentData.method2);

        // Checkout é único se:
        // - Apenas method1 é checkout e method2 não está ativo/vazio, OU
        // - Apenas method2 é checkout e method1 não existe/está vazio
        const checkoutIsOnlyMethod = (method1IsCheckout && !hasMethod2) || (method2IsCheckout && !hasMethod1) || (method1IsCheckout && method2IsCheckout);

        // Se checkout não é o único método, não incluir mensagem "created"
        const createdMessage = checkoutIsOnlyMethod
            ? (selectedFeedback.paymentCreatedMessage || 'Seu pagamento foi criado e está aguardando processamento.')
            : '';

        return {
            status: 'configured',
            paymentId: paymentId,
            paymentStatus: paymentStatus,
            feedbackTimeSeconds: feedbackTimeSeconds,
            successMessage: selectedFeedback.paymentSuccessMessage || 'Seu pagamento foi processado com sucesso!',
            deniedMessage: selectedFeedback.paymentDeniedMessage || 'Seu pagamento foi negado.',
            processingMessage: selectedFeedback.paymentProcessingMessage || 'Seu pagamento está sendo processado.',
            createdMessage: createdMessage
        };

    } catch (error) {
        return { status: 'error', message: 'Erro ao configurar feedback: ' + error.message };
    }
}

