async function run(feedbackConfig, checkoutRequest, checkoutResponse, orderDetailsJSON) {
    try {
        if (!feedbackConfig) {
            return JSON.stringify({ status: 'skipped', message: 'Sem config' });
        }

        var config = {};
        try {
            config = JSON.parse(feedbackConfig);
        } catch (e) {
            return JSON.stringify({ status: 'error', message: 'Config inválido' });
        }

        if (config.status !== 'configured') {
            return JSON.stringify({ status: 'skipped', message: 'Config não configurado' });
        }

        const paymentStatus = config.paymentStatus || 'unknown';
        const timestamp = Math.floor(Date.now() / 1000);

        // Extrair reference_id do orderDetailsJSON (deve corresponder ao enviado no order_details)
        let referenceId = config.paymentId || '';
        try {
            const orderDetails = typeof orderDetailsJSON === 'string' ? JSON.parse(orderDetailsJSON) : orderDetailsJSON;
            if (orderDetails &&
                orderDetails.interactive &&
                orderDetails.interactive.action &&
                orderDetails.interactive.action.parameters &&
                orderDetails.interactive.action.parameters.reference_id) {
                referenceId = orderDetails.interactive.action.parameters.reference_id;
            }
        } catch (e) { /* usa fallback config.paymentId */ }

        if (!referenceId) {
            return JSON.stringify({ status: 'skipped', message: 'reference_id ausente — order_status não enviado' });
        }

        // Mapear status do Checkout para valores suportados pela Meta API
        // Order status: pending | processing | partially_shipped | shipped | completed | canceled
        // Payment status: pending | captured | failed
        let orderStatus = 'processing';
        let paymentStatusMeta = 'pending';
        let bodyText = config.processingMessage || 'Processando pagamento...';

        switch (paymentStatus) {
            case 'Succeeded':
                orderStatus = 'completed';
                paymentStatusMeta = 'captured';
                bodyText = config.successMessage || 'Seu pagamento foi processado com sucesso!';
                break;
            case 'Denied':
            case 'Failed':
                orderStatus = 'canceled';
                paymentStatusMeta = 'failed';
                bodyText = config.deniedMessage || 'Seu pagamento foi negado.';
                break;
            case 'Processing':
            case 'Pending':
                orderStatus = 'processing';
                paymentStatusMeta = 'pending';
                bodyText = config.processingMessage || 'Seu pagamento está sendo processado.';
                break;
            case 'Created':
                orderStatus = 'pending';
                paymentStatusMeta = 'pending';
                // Só usa mensagem "created" se configurada e não vazia
                // (será vazia quando checkout não for o único método)
                bodyText = config.createdMessage || '';
                break;
            default:
                orderStatus = 'processing';
                paymentStatusMeta = 'pending';
                bodyText = config.processingMessage || 'Processando pagamento...';
                break;
        }

        // Não enviar se bodyText estiver vazio (ex: Created sem mensagem configurada)
        if (!bodyText) {
            return JSON.stringify({ status: 'skipped', message: 'Sem mensagem para este status' });
        }

        const orderStatusJSON = {
            recipient_type: 'individual',
            type: 'interactive',
            interactive: {
                type: 'order_status',
                body: {
                    text: bodyText
                },
                action: {
                    name: 'review_order',
                    parameters: {
                        reference_id: referenceId,
                        order: {
                            status: orderStatus
                        },
                        payment: {
                            status: paymentStatusMeta,
                            timestamp: timestamp
                        }
                    }
                }
            }
        };

        return JSON.stringify({
            status: 'completed',
            orderStatusJSON: orderStatusJSON,
            paymentId: config.paymentId,
            paymentStatus: paymentStatus,
            checkoutResponse: checkoutResponse
        });

    } catch (error) {
        return JSON.stringify({
            status: 'error',
            message: error.message || error.toString()
        });
    }
}

